<?php

declare(strict_types=1);
namespace Tests\Feature\TeachingAssignments;
use App\Models\{AcademicYear,Classroom,GradeLevel,Personnel,Subject,TeachingImportRow,User};use App\Services\Personnel\SimpleXlsxService;use App\Services\TeachingAssignments\{TeachingAssignmentImportService,WorkbookClassroomParser,WorkbookNameMatcher};use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\Storage;use Tests\TestCase;
class TeachingWorkbookParserRegressionTest extends TestCase
{
 use RefreshDatabase;
 public function test_sheet_specific_parser_only_creates_domain_rows_with_required_source_counts():void{$year=AcademicYear::create(['name'=>'2026/2027','starts_at'=>'2026-07-01','ends_at'=>'2027-06-30']);$gradeNames=[1=>'I',2=>'II',3=>'III',4=>'IV',5=>'V',6=>'VI'];$grades=[];foreach($gradeNames as $number=>$roman)$grades[$number]=GradeLevel::create(['number'=>$number,'name'=>'Kelas '.$roman,'roman_label'=>$roman,'sort_order'=>$number]);$roomLabels=['Kelas I As-Salam','Kelas I Ar-Rahman','Kelas I Ar-Rahim','Kelas II A','Kelas II B','Kelas III A','Kelas III B','Kelas IV A','Kelas IV B','Kelas V A','Kelas V B','Kelas VI A'];foreach($roomLabels as $index=>$label){preg_match('/Kelas (VI|IV|V|III|II|I)/',$label,$match);$number=array_search($match[1],$gradeNames,true);$name=trim(substr($label,strlen('Kelas '.$match[1])));Classroom::create(['academic_year_id'=>$year->id,'grade_level_id'=>$grades[$number]->id,'code'=>$match[1].' '.($index+1),'name'=>$name,'program_type'=>$label==='Kelas I As-Salam'?'full_day':'regular']);}$people=[];foreach(range(1,24) as $index)$people[]=Personnel::create(['full_name'=>'Guru '.$index,'gender'=>'male','employment_status'=>'GTY','position'=>'Guru','is_active'=>true]);foreach(range(1,22) as $index)Subject::create(['code'=>chr(64+$index),'name'=>'Mapel '.$index,'sort_order'=>$index,'is_active'=>true]);$database=[];foreach(range(10,33) as $row)$database[$row][3]='Guru '.($row-9);$loadCounts=[17,14,14,18,18,18,18];$totals=[62,42,42,50,50,50,50];foreach(range(10,31) as $row){$subject=$row-9;$database[$row][5]=chr(64+$subject);$database[$row][6]='Mapel '.$subject;foreach(range(8,14) as $offset=>$column)if($subject<=$loadCounts[$offset])$database[$row][$column]=$subject===1?1+$totals[$offset]-$loadCounts[$offset]:1;}foreach($roomLabels as $index=>$label){$row=10+$index;$database[$row][16]=$index+1;$database[$row][17]=$label;$database[$row][18]='Guru '.($index+1);}foreach(range(8,14) as $offset=>$column)$database[34][$column]=$totals[$offset];$legger=[3=>[2=>'Nama',3=>'Tugas Tambahan',4=>'Kelas'],4=>[]];foreach(range(5,26) as $column)$legger[4][$column]='Mapel '.($column-4);$legger[5]=[2=>'Guru 1',3=>'Wali Kelas',4=>'Kelas I, II, III, IV, V & VI'];foreach(range(5,20) as $column)$legger[5][$column]='x';$legger[6]=[2=>'Guru 2',3=>'Wali Kelas',4=>'Kelas I As-Salam',5=>'x'];$legger[7]=[2=>'Guru 3',3=>'Wali Kelas',4=>'Kelas I As-Salam'];foreach(range(21,26) as $column)$legger[7][$column]='x';foreach(range(8,19) as $row)$legger[$row]=[2=>'Guru '.($row-4),3=>'Wali Kelas',4=>'Kelas II A'];foreach(range(29,34) as $row)$legger[$row]=[1=>$row-4,2=>'BUKAN DATA',5=>'x'];$sheets=['DATABASE'=>$database,'LEGGER'=>$legger,'PEMBAGIAN TUGAS MAPEL'=>[8=>[2=>'Guru Contoh, S.Pd.',10=>42]]];$xlsx=new class($sheets) extends SimpleXlsxService {public function __construct(private array $fixture){}public function read(string $path):array{return $this->fixture;}};Storage::fake('local');$service=new TeachingAssignmentImportService($xlsx,new WorkbookNameMatcher,new WorkbookClassroomParser(new WorkbookNameMatcher));$batch=$service->preview(UploadedFile::fake()->create('pembagian.xlsx',10,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'),$year->id,User::factory()->create());$this->assertSame(3,$batch->sheet_count);$this->assertSame(22,$batch->subject_count);$this->assertSame(117,$batch->structure_load_count);$this->assertSame(24,$batch->personnel_count);$this->assertSame(12,$batch->classroom_count);$this->assertSame(199,$batch->assignment_candidate_count);$this->assertSame(15,$batch->additional_duty_count);$this->assertSame(1,$batch->conflict_count);$this->assertSame([62,42,42,50,50,50,50],$batch->summary['database']['reference_totals']);$this->assertFalse(TeachingImportRow::where('sheet_name','LEGGER')->whereBetween('row_number',[29,34])->exists());$this->assertFalse(TeachingImportRow::where('sheet_name','DATABASE')->where('row_number',34)->exists());$this->assertFalse(TeachingImportRow::where('sheet_name','PEMBAGIAN TUGAS MAPEL')->exists());$this->assertSame('Template cetak ditemukan dan berhasil divalidasi.',$batch->summary['template']['status']);}
}
